set-variable.value:
@{
        if (context.Variables.ContainsKey("callerToken"))
        {
            var jwt = (Jwt)context.Variables["callerToken"];
            if (jwt.Claims.ContainsKey("oid"))
            {
                return jwt.Claims["oid"].FirstOrDefault();
            }
            if (jwt.Claims.ContainsKey("appid"))
            {
                return jwt.Claims["appid"].FirstOrDefault();
            }
        }
        if (context.Subscription != null)
        {
            return context.Subscription.Id;
        }
        return context.Request.IpAddress;
    }

@{
                var models = new JArray();
                try
                {
                    var armResponse = (IResponse)context.Variables["armResponse"];
                    if (armResponse != null && armResponse.StatusCode == 200)
                    {
                        var deployments = armResponse.Body.As<JObject>()["value"] as JArray;
                        if (deployments != null)
                        {
                            foreach (var deployment in deployments)
                            {
                                var props = deployment["properties"];
                                if (props == null) { continue; }

                                // Only Anthropic-format deployments speak the
                                // Messages API this gateway exposes. A GPT or
                                // Llama deployment listed here would appear in
                                // the picker and then fail on every request.
                                var model = props["model"];
                                if (model == null || (string)model["format"] != "Anthropic") { continue; }
                                if ((string)props["provisioningState"] != "Succeeded") { continue; }

                                var name = (string)deployment["name"];
                                var created = props["createdAt"] != null
                                    ? (string)props["createdAt"]
                                    : DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ");

                                var entry = new JObject();
                                entry["type"] = "model";
                                // The Messages API keys off the DEPLOYMENT
                                // name, not the underlying model id, so that
                                // is what the client must send back.
                                entry["id"] = name;
                                entry["display_name"] = name;
                                entry["created_at"] = created;
                                models.Add(entry);
                            }
                        }
                    }
                }
                catch (Exception)
                {
                    // Fall through to an empty list; the client keeps whatever
                    // model list it was configured with.
                }

                var payload = new JObject();
                payload["data"] = models;
                payload["has_more"] = false;
                payload["first_id"] = models.Count > 0 ? models[0]["id"] : null;
                payload["last_id"] = models.Count > 0 ? models[models.Count - 1]["id"] : null;
                return payload.ToString(Newtonsoft.Json.Formatting.None);
            }

@{
            var sb = new System.Text.StringBuilder();
            try
            {
                // preserveContent: true - the body must survive for the backend.
                var body = context.Request.Body.As<JObject>(true);
                var messages = body["messages"] as JArray;
                if (messages != null)
                {
                    for (int i = messages.Count - 1; i >= 0; i--)
                    {
                        var message = messages[i];
                        if ((string)message["role"] != "user") { continue; }

                        var content = message["content"];
                        if (content == null) { break; }

                        // content is either a bare string or an array of blocks.
                        if (content.Type == JTokenType.String)
                        {
                            sb.Append((string)content);
                        }
                        else
                        {
                            var blocks = content as JArray;
                            if (blocks != null)
                            {
                                foreach (var block in blocks)
                                {
                                    if ((string)block["type"] == "text")
                                    {
                                        sb.Append((string)block["text"]).Append("\n");
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
            }
            catch (Exception)
            {
                // Unparseable body: leave the prompt empty so the guardrail is
                // skipped rather than failing an otherwise valid request.
            }
            var text = sb.ToString().Trim();
            // Content Safety caps input at 10,000 characters. Truncating to the
            // first 9,000 would let an attack hide behind a long paste: a user
            // turn that opens with a pasted file and ends with the injection
            // would never be inspected. Keep both ends instead, so an attack has
            // to be buried in the middle of a >9,000 character turn to evade.
            if (text.Length <= 9000) { return text; }
            return text.Substring(0, 4500) +

send-request.set-body:
@{
                  var payload = new JObject();
                  payload["userPrompt"] = (string)context.Variables["guardrailPrompt"];
                  payload["documents"] = new JArray();
                  return payload.ToString(Newtonsoft.Json.Formatting.None);
              }

@{
                  var payload = new JObject();
                  payload["text"] = (string)context.Variables["guardrailPrompt"];
                  var categories = new JArray();
                  categories.Add("Hate");
                  categories.Add("Sexual");
                  categories.Add("Violence");
                  categories.Add("SelfHarm");
                  payload["categories"] = categories;
                  // 0-7 rather than 0/2/4/6, so the threshold can be tuned finely.
                  payload["outputType"] = "EightSeverityLevels";
                  return payload.ToString(Newtonsoft.Json.Formatting.None);
              }

set-variable.value:
@{
                try
                {
                    var shield = (IResponse)context.Variables["shieldResponse"];
                    if (shield != null && shield.StatusCode == 200)
                    {
                        var analysis = shield.Body.As<JObject>()["userPromptAnalysis"];
                        if (analysis != null && (bool)analysis["attackDetected"])
                        {
                            return "prompt_shield";
                        }
                    }
                }
                catch (Exception) { }

                try
                {
                    var analyze = (IResponse)context.Variables["analyzeResponse"];
                    if (analyze != null && analyze.StatusCode == 200)
                    {
                        var categories = analyze.Body.As<JObject>()["categoriesAnalysis"] as JArray;
                        if (categories != null)
                        {
                            foreach (var category in categories)
                            {
                                var severity = (int)category["severity"];
                                if (severity >= __GUARDRAIL_SEVERITY_THRESHOLD__)
                                {
                                    return ((string)category["category"]).ToLowerInvariant() + ":" + severity.ToString();
                                }
                            }
                        }
                    }
                }
                catch (Exception) { }

                return "allow";
            }

return-response.set-body:
@{
                      var verdict = (string)context.Variables["guardrailVerdict"];
                      var reason = verdict == "prompt_shield"
                          ? "a prompt injection or jailbreak attempt was detected"
                          : "the prompt scored at or above the configured harm threshold (" + verdict + ")";
                      var error = new JObject();
                      error["type"] = "permission_error";
                      error["message"] = "Blocked by the AI gateway before the request reached the model: " + reason
                          + ". Enforced by Azure AI Content Safety, not by the model's own refusal behaviour.";
                      var root = new JObject();
                      root["type"] = "error";
                      root["error"] = error;
                      return root.ToString(Newtonsoft.Json.Formatting.None);
                  }
